-- Wrap of the 2026-11-15 ve-social-schedule chat (2026-11-21). Additive canon only; nothing existing is changed. Safe to run twice.
update knowledge_records set body = body || jsonb_build_object('faces_first_2026_11_19', 'Sean, 2026-11-19 (playbook ve-social-schedule): "we should be doing more posts that showcase the businesses, not so much the guides... the jury is still out on AI. So let''s lead more with the faces of the people, and just keep taking note of the performance of our posts." Real people and businesses lead; Guides only as the call to action; podcast clips that spotlight a business or person (the locked podcast spotlight reel); the 2-day rule before any collaborator; this direction outranks the older "new Guide art per post" rule above.'), updated_at = now() where slug = 'canon-ve-design-team' and not (body ? 'faces_first_2026_11_19');
update knowledge_records set body = body || jsonb_build_object('our_template_2026_11_15', 'The city carousel is now built on our own carousel template (scripts/brand-templates/carousel.js), not Canva: the Philadelphia pilot (public/social/week-2026-11-16/philly/, final spec public/social/review-2026-11-16/direct-response/src/philly.json) went out Thu Nov 19 after Sean approved the week. The Canva designs stay the source of each city''s five places and photos. Cover: communities/<slug>/square.jpg (drawn for the square, never cropped from wide). Four more built 2026-11-15 (South Florida, Los Angeles, New York, Atlanta; public/social/week-2026-11-23/cities/), proposed, not scheduled.'), updated_at = now() where slug = 'canon-ve-city-carousel' and not (body ? 'our_template_2026_11_15');
